// A clearing, cabin settlement, and old watchtower landmark.
function cabin(x,z,w=8,d=6){const y=terrainY(x,z);const g=new THREE.Group();g.position.set(x,y,z);box(g,0,.24,0,w,.48,d,roofMat);const wall=mat('#d1bd8f');box(g,0,1.9,0,w,3.2,d,wall);box(g,3,1.4,d/2+.03,1.1,2.4,.15,mat('#433b2f'));for(const wx of [-w*.28,w*.28])box(g,wx,2.1,d/2+.04,1.2,1.1,.12,mat('#5a7775',.4));const roof=new THREE.Mesh(new THREE.ConeGeometry(Math.hypot(w,d)*.58,2.7,4),mat('#58624f'));roof.position.y=4.75;roof.rotation.y=Math.PI/4;roof.castShadow=true;g.add(roof);scene.add(g)}
cabin(-21,-14,9,7);cabin(-31,-22,7,6);cabin(-12,-27,8,7);cabin(26,19,9,7);cabin(36,25,7,6);cabin(30,9,8,6);
const tower=new THREE.Group();tower.position.set(-2,terrainY(-2,-30),-30);box(tower,0,3,0,3,6,3,mat('#7d7258'));for(let i=0;i<4;i++){const post=box(tower,0,7,0,7,.35,.35,barkMat,0,i*Math.PI/2);post.position.x=Math.sin(i*Math.PI/2)*3;post.position.z=Math.cos(i*Math.PI/2)*3}box(tower,0,6.1,0,6.4,.3,6.4,mat('#647364'));const cap=new THREE.Mesh(new THREE.ConeGeometry(5,2.5,4),mat('#454e47'));cap.position.y=8.2;cap.rotation.y=Math.PI/4;cap.castShadow=true;tower.add(cap);scene.add(tower);
// Dirt trails and scattered field details.
const pathMat=new THREE.MeshStandardMaterial({color:'#a38f68',roughness:1});for(const [x,z,r] of [[-20,-20,2.2],[27,18,2.4],[-3,-30,2]]){const path=new THREE.Mesh(new THREE.CircleGeometry(r,20),pathMat);path.rotation.x=-Math.PI/2;path.position.set(x,terrainY(x,z)+.04,z);scene.add(path)}
// Storm wall and supply caches.
const stormMat=new THREE.MeshBasicMaterial({color:'#7adcf5',transparent:true,opacity:.78});const stormRing=new THREE.Mesh(new THREE.TorusGeometry(1,.22,8,160),stormMat);stormRing.rotation.x=Math.PI/2;stormRing.position.y=.2;scene.add(stormRing);
const caches=[];function makeCache(x,z,type='ammo'){const g=new THREE.Group();g.position.set(x,terrainY(x,z)+.1,z);const glow=new THREE.PointLight(type==='med'?'#9dff89':'#f1cb75',2.2,7);glow.position.y=1.5;g.add(glow);box(g,0,.55,0,1.4,1.1,1.2,crateMat);box(g,0,1.13,0,1.5,.18,1.3,mat('#c39b61'));box(g,0,1.23,0,.18,.13,1.35,mat(type==='med'?'#9dff89':'#f4d184'));scene.add(g);caches.push({group:g,x,z,type,active:true})}
for(const [x,z,t] of [[-24,-17,'ammo'],[-9,-26,'med'],[30,22,'ammo'],[34,12,'med'],[5,-38,'ammo'],[-42,20,'med'],[44,-27,'ammo'],[-49,-17,'ammo'],[13,49,'med'],[-9,24,'ammo']])makeCache(x,z,t);
function makeFighter(color='#c8f169',isEnemy=false){const root=new THREE.Group(),model=new THREE.Group();root.add(model);const suit=mat(color),dark=mat('#25322e'),skin=mat('#c69470'),helmet=mat(isEnemy?'#db654f':'#9fbd70',.58,.12);function part(geo,m,x,y,z,sx=1,sy=1,sz=1){const o=new THREE.Mesh(geo,m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;model.add(o);return o}part(new THREE.CapsuleGeometry(.47,.75,4,8),suit,0,1.35,0,1,.9,.72);part(new THREE.SphereGeometry(.37,12,10),helmet,0,2.23,0,1,.94,.95);part(new THREE.BoxGeometry(.4,.13,.13),dark,0,2.22,.33);for(const side of [-1,1]){part(new THREE.CapsuleGeometry(.16,.62,3,6),suit,side*.57,1.36,.1,1,1,1).rotation.z=side*.16;part(new THREE.CapsuleGeometry(.18,.62,3,6),dark,side*.26,.48,0,1,1,1).rotation.z=-side*.08}const gun=new THREE.Group();gun.position.set(.28,1.46,.63);model.add(gun);const barrel=box(gun,0,0,.45,.16,.17,.95,metalMat);box(gun,0,-.16,.2,.2,.25,.3,mat('#2d3933'));const muzzle=new THREE.Mesh(new THREE.SphereGeometry(.13,8,6),mat('#ffd66e',.25));muzzle.position.z=.98;gun.add(muzzle);muzzle.visible=false;const shadow=new THREE.Mesh(new THREE.CircleGeometry(.65,16),new THREE.MeshBasicMaterial({color:'#142018',transparent:true,opacity:.25,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.015;root.add(shadow);return {root,model,gun,muzzle}}
const playerObj=makeFighter('#beca8b',false);scene.add(playerObj.root);
const player={...playerObj,x:0,z:0,angle:0,hp:100,shield:50,ammo:30,reserve:120,kills:0,fireCd:0,reload:0,alive:true,speed:8.7};
let bots=[],bullets=[],sparks=[],gameStarted=false,gameOver=false,elapsed=0,stormDuration=120,stormRadius=81,lastTime=0,shootHeld=false,fireTouch=false,keys={},mouse={x:innerWidth/2,y:innerHeight/2,down:false},touchMove={x:0,y:0};
function spawnBot(i){let x,z;do{x=rand(-69,69);z=rand(-69,69)}while(Math.hypot(x,z)<19||Math.hypot(x,z)>77);const colors=['#be6c55','#637a9d','#cf9b51','#9a6f9e','#608b79','#b86a6b'];const avatar=makeFighter(pick(colors),true);avatar.root.position.set(x,terrainY(x,z),z);scene.add(avatar.root);bots.push({...avatar,x,z,hp:70,alive:true,fireCd:rand(1,4),speed:rand(2.4,3.5),wander:rand(0,6),angle:rand(0,6),hitFlash:0})}
for(let i=0;i<11;i++)spawnBot(i);
function announce(text,kill=false){const el=document.querySelector('#toast');el.textContent=text;el.classList.toggle('kill',kill);el.classList.add('show');clearTimeout(announce.timer);announce.timer=setTimeout(()=>el.classList.remove('show'),1400)}
function updateHud(){document.querySelector('#health-fill').style.width=player.hp+'%';document.querySelector('#health-num').textContent=Math.ceil(player.hp);document.querySelector('#shield-fill').style.width=(player.shield/100*100)+'%';document.querySelector('#shield-num').textContent=Math.ceil(player.shield);document.querySelector('#ammo').textContent=player.ammo;document.querySelector('#reserve').textContent=player.reserve;document.querySelector('#kills').textContent=player.kills;document.querySelector('#alive').textContent=1+bots.filter(b=>b.alive).length}

