function updateHud(){document.querySelector('#health-fill').style.width=player.hp+'%';document.querySelector('#health-num').textContent=Math.ceil(player.hp);document.querySelector('#shield-fill').style.width=player.shield+'%';document.querySelector('#shield-num').textContent=Math.ceil(player.shield);document.querySelector('#ammo').textContent=player.ammo;document.querySelector('#reserve').textContent=player.reserve;document.querySelector('#kills').textContent=player.kills;document.querySelector('#alive').textContent=1+bots.filter(b=>b.alive).length}
const aimPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0),raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let aimPoint=new THREE.Vector3(0,0,-20);
function aimAt(px,py){pointer.x=px/innerWidth*2-1;pointer.y=-(py/innerHeight)*2+1;raycaster.setFromCamera(pointer,camera);const out=new THREE.Vector3();if(raycaster.ray.intersectPlane(aimPlane,out)){aimPoint.copy(out);const dx=out.x-player.x,dz=out.z-player.z;if(Math.hypot(dx,dz)>1)player.angle=Math.atan2(dx,dz)}}
function tracer(a,b,color='#f5df9e',life=.075){const geo=new THREE.BufferGeometry().setFromPoints([a,b]);const line=new THREE.Line(geo,new THREE.LineBasicMaterial({color,transparent:true,opacity:.9}));scene.add(line);sparks.push({object:line,life,max:life})}
function impact(x,z,color='#ffd06a'){const g=new THREE.Group();g.position.set(x,terrainY(x,z)+.4,z);const puff=new THREE.Mesh(new THREE.SphereGeometry(.28,8,6),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.95}));g.add(puff);scene.add(g);sparks.push({object:g,life:.2,max:.2,scale:true})}
function shoot(){if(!gameStarted||gameOver||!player.alive||player.reload>0||player.fireCd>0)return;if(player.ammo<=0){reload();return}player.fireCd=.135;player.ammo--;player.muzzle.visible=true;setTimeout(()=>player.muzzle.visible=false,55);const dx=Math.sin(player.angle),dz=Math.cos(player.angle),origin=new THREE.Vector3(player.x+dx*.7,terrainY(player.x,player.z)+1.55,player.z+dz*.7);let best=null,bestDist=58;for(const b of bots){if(!b.alive)continue;const vx=b.x-player.x,vz=b.z-player.z,along=vx*dx+vz*dz,side=Math.abs(vx*dz-vz*dx),distance=Math.hypot(vx,vz);if(along>0&&along<bestDist&&side<1.35&&distance<58){best=b;bestDist=along}}const end=best?new THREE.Vector3(best.x,terrainY(best.x,best.z)+1.4,best.z):new THREE.Vector3(player.x+dx*55,terrainY(player.x+dx*55,player.z+dz*55)+1,player.z+dz*55);tracer(origin,end,'#ffe19a');if(best){best.hp-=34;best.hitFlash=.12;best.model.traverse(o=>{if(o.isMesh&&o.material.color){o.userData.oldColor=o.material.color.getHex();o.material.color.set('#fff0bc')}});impact(best.x,best.z);if(best.hp<=0){best.alive=false;best.root.visible=false;player.kills++;announce('RIVAL ELIMINATED',true);if(bots.every(v=>!v.alive))finish(true)}}updateHud()}
function reload(){if(player.reload>0||player.ammo===30||player.reserve<=0)return;player.reload=1.15;announce('RELOADING');setTimeout(()=>{if(player.reload>0){const n=Math.min(30-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n;player.reload=0;updateHud()}},1150)}
function damagePlayer(amount){if(!player.alive)return;let rest=amount;if(player.shield>0){const n=Math.min(player.shield,rest);player.shield-=n;rest-=n}player.hp=Math.max(0,player.hp-rest);const flash=document.querySelector('#damage-flash');flash.classList.add('hit');setTimeout(()=>flash.classList.remove('hit'),100);updateHud();if(player.hp<=0){player.alive=false;finish(false)}}
function finish(win){if(gameOver)return;gameOver=true;document.querySelector('#end-title').textContent=win?'VICTORY':'ELIMINATED';document.querySelector('#end-label').textContent=win?'LAST LIGHT STANDING':'BATTLE REPORT';document.querySelector('#end-copy').textContent=`${player.kills} eliminations · ${Math.floor(elapsed)} seconds survived`;document.querySelector('#end-screen').style.display='grid';document.exitPointerLock?.()}
function movePlayer(dt){let mx=0,mz=0;if(keys.KeyW||keys.ArrowUp)mz-=1;if(keys.KeyS||keys.ArrowDown)mz+=1;if(keys.KeyA||keys.ArrowLeft)mx-=1;if(keys.KeyD||keys.ArrowRight)mx+=1;mx+=touchMove.x;mz+=touchMove.y;const mag=Math.hypot(mx,mz);if(mag>1){mx/=mag;mz/=mag}player.x=clamp(player.x+mx*player.speed*dt,-86,86);player.z=clamp(player.z+mz*player.speed*dt,-86,86);player.root.position.set(player.x,terrainY(player.x,player.z),player.z);player.model.rotation.y=player.angle}
function updateBots(dt){for(const b of bots){if(!b.alive)continue;b.fireCd-=dt;b.wander+=dt;const dx=player.x-b.x,dz=player.z-b.z,dist=Math.hypot(dx,dz);let vx=0,vz=0;if(dist<43){const ang=Math.atan2(dx,dz);b.angle=ang;if(dist>13){vx=Math.sin(ang);vz=Math.cos(ang)}else{const strafe=Math.sin(elapsed*1.6+b.wander)*.5;vx=Math.sin(ang+Math.PI/2)*strafe;vz=Math.cos(ang+Math.PI/2)*strafe}if(dist<36&&b.fireCd<=0){b.fireCd=rand(1.05,2.1);bullets.push({x:b.x+Math.sin(ang)*.5,z:b.z+Math.cos(ang)*.5,y:terrainY(b.x,b.z)+1.5,vx:Math.sin(ang)*18,vz:Math.cos(ang)*18,life:dist/18+1,damage:rand(7,12),enemy:true})}}else{b.angle+=Math.sin(b.wander)*dt*.25;vx=Math.sin(b.angle)*.35;vz=Math.cos(b.angle)*.35}b.x=clamp(b.x+vx*b.speed*dt,-86,86);b.z=clamp(b.z+vz*b.speed*dt,-86,86);b.root.position.set(b.x,terrainY(b.x,b.z),b.z);b.model.rotation.y=b.angle;if(b.hitFlash>0){b.hitFlash-=dt;if(b.hitFlash<=0)b.model.traverse(o=>{if(o.isMesh&&o.userData.oldColor){o.material.color.setHex(o.userData.oldColor);delete o.userData.oldColor}})}if(Math.hypot(b.x,b.z)>stormRadius){b.hp-=dt*5;if(b.hp<=0){b.alive=false;b.root.visible=false}}}}
function updateBullets(dt){for(let i=bullets.length-1;i>=0;i--){const b=bullets[i];b.x+=b.vx*dt;b.z+=b.vz*dt;b.life-=dt;if(b.enemy&&Math.hypot(b.x-player.x,b.z-player.z)<.9&&Math.abs(b.y-(terrainY(player.x,player.z)+1.2))<1.2){damagePlayer(b.damage);b.life=0}if(b.life<=0){bullets.splice(i,1);continue}if(Math.random()<.25)impact(b.x,b.z,'#ffb77a')}}

