function updateBullets(dt){for(let i=bullets.length-1;i>=0;i--){const b=bullets[i];b.x+=b.vx*dt;b.z+=b.vz*dt;b.life-=dt;if(b.mesh)b.mesh.position.set(b.x,b.y,b.z);if(b.enemy&&Math.hypot(b.x-player.x,b.z-player.z)<.9&&Math.abs(b.y-(terrainY(player.x,player.z)+1.2))<1.2){damagePlayer(b.damage);b.life=0}if(b.life<=0){if(b.mesh)scene.remove(b.mesh);bullets.splice(i,1);continue}}}
function updateWorld(dt){if(!gameStarted||gameOver)return;elapsed+=dt;player.fireCd=Math.max(0,player.fireCd-dt);if(player.reload>0)player.reload=Math.max(0,player.reload-dt);if(shootHeld||fireTouch)shoot();movePlayer(dt);updateBots(dt);updateBullets(dt);for(const c of caches){if(c.active&&Math.hypot(c.x-player.x,c.z-player.z)<2.1){c.active=false;c.group.visible=false;if(c.type==='med'){player.hp=Math.min(100,player.hp+35);player.shield=Math.min(100,player.shield+10);announce('MED KIT +35')}else{player.reserve=Math.min(240,player.reserve+45);announce('AMMO +45')}updateHud()}}if(elapsed<stormDuration){document.querySelector('#storm-time').textContent=`${String(Math.floor((stormDuration-elapsed)/60)).padStart(2,'0')}:${String(Math.floor((stormDuration-elapsed)%60)).padStart(2,'0')}`}else{document.querySelector('#storm-time').textContent='CLOSING';stormRadius=Math.max(14,81-(elapsed-stormDuration)*.46);if(Math.hypot(player.x,player.z)>stormRadius)damagePlayer(dt*7);for(const b of bots)if(b.alive&&Math.hypot(b.x,b.z)>stormRadius)b.hp-=dt*7}stormRing.scale.set(stormRadius,stormRadius,stormRadius);stormRing.material.opacity=.6+Math.sin(elapsed*5)*.2;updateMinimap()}
function updateMinimap(){const layer=document.querySelector('#map-enemies');layer.innerHTML='';for(const b of bots){if(!b.alive)continue;const d=document.createElement('i');d.className='map-enemy';d.style.left=`${50+b.x/90*46}%`;d.style.top=`${50+b.z/90*46}%`;layer.appendChild(d)}const dot=document.querySelector('.map-dot');dot.style.left=`${50+player.x/90*46}%`;dot.style.top=`${50+player.z/90*46}%`}
const cameraTarget=new THREE.Vector3();function updateCamera(dt){if(gameStarted){const backX=-Math.sin(player.angle)*11,backZ=-Math.cos(player.angle)*11;cameraTarget.set(player.x+backX,terrainY(player.x,player.z)+10,player.z+backZ);camera.position.lerp(cameraTarget,1-Math.exp(-dt*3.2));const focus=new THREE.Vector3(player.x+Math.sin(player.angle)*3,terrainY(player.x,player.z)+1.25,player.z+Math.cos(player.angle)*3);camera.lookAt(focus)}else{camera.position.lerp(new THREE.Vector3(26,27,45),1-Math.exp(-dt*.4));camera.lookAt(0,1,-7)}}
function animate(now){requestAnimationFrame(animate);const dt=Math.min(.045,(now-lastTime)/1000||.016);lastTime=now;updateWorld(dt);updateCamera(dt);for(let i=sparks.length-1;i>=0;i--){const s=sparks[i];s.life-=dt;if(s.scale){const t=1-s.life/s.max;s.object.scale.setScalar(1+t*2);s.object.children[0].material.opacity=Math.max(0,s.life/s.max)}else if(s.object.material)s.object.material.opacity=Math.max(0,s.life/s.max);if(s.life<=0){scene.remove(s.object);sparks.splice(i,1)}}renderer.render(scene,camera)}requestAnimationFrame(animate);
function startGame(){if(gameStarted)return;gameStarted=true;document.querySelector('#menu').style.display='none';document.querySelector('#hud').style.display='block';document.body.classList.add('playing');camera.position.set(0,12,12);updateHud();aimAt(innerWidth/2,innerHeight/2);announce('DROP COMPLETE — SURVIVE');}
document.querySelector('#start').addEventListener('click',startGame);document.querySelector('#again').addEventListener('click',()=>location.reload());
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
window.addEventListener('keydown',e=>{keys[e.code]=true;if(e.code==='KeyR')reload();if(e.code==='Space'){e.preventDefault();shoot()}});window.addEventListener('keyup',e=>keys[e.code]=false);
canvas.addEventListener('pointermove',e=>{if(gameStarted){aimAt(e.clientX,e.clientY)}});canvas.addEventListener('pointerdown',e=>{if(!gameStarted)return;mouse.down=true;shootHeld=true;aimAt(e.clientX,e.clientY)});window.addEventListener('pointerup',()=>{mouse.down=false;shootHeld=false});
const stick=document.querySelector('#stick');let stickPointer=null;stick.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);updateStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)updateStick(e)});function updateStick(e){const r=stick.getBoundingClientRect(),dx=(e.clientX-(r.left+r.width/2))/(r.width*.38),dy=(e.clientY-(r.top+r.height/2))/(r.height*.38),m=Math.hypot(dx,dy),k=m>1?1/m:1;touchMove.x=dx*k;touchMove.y=dy*k;stick.style.setProperty('--sx',`${34+touchMove.x*24}px`);stick.style.setProperty('--sy',`${34+touchMove.y*24}px`);stick.style.setProperty('background',`radial-gradient(circle at ${50+touchMove.x*24}% ${50+touchMove.y*24}%,#c8f16922,transparent 50%),#07110f77`)}stick.addEventListener('pointerup',()=>{stickPointer=null;touchMove={x:0,y:0};stick.style.background=''});stick.addEventListener('pointercancel',()=>{stickPointer=null;touchMove={x:0,y:0}});
const fireButton=document.querySelector('#fire-touch');fireButton.addEventListener('pointerdown',e=>{e.preventDefault();fireTouch=true;fireButton.setPointerCapture(e.pointerId)});fireButton.addEventListener('pointerup',()=>fireTouch=false);fireButton.addEventListener('pointercancel',()=>fireTouch=false);document.querySelector('#reload-touch').addEventListener('pointerdown',e=>{e.preventDefault();reload()});
// Touch on the open battlefield aims and fires; controls are excluded.
canvas.addEventListener('touchstart',e=>{if(!gameStarted)return;const t=e.changedTouches[0];aimAt(t.clientX,t.clientY);if(e.target===canvas)shoot()},{passive:true});
